/** Identity function */
export declare const identity: <T>(x: T) => T;
/** Last item in array */
export declare const last: <T>(arr: T[]) => T;
/** Type guard to check that value is NOT undefined */
export declare const isDefined: <T>(x: T | undefined) => x is T;
/** Type guard for strings */
export declare const isString: (x: any) => x is string;
/** Type guard for objects */
export declare const isObject: (x: any) => x is Record<string, any>;
